{
  "type": "Double-page comic panel",
  "style": "Highly detailed realistic comic book style, black and white, halftone screen, dramatic lighting, psychological thriller.",
  "global_elements": {
    "protagonist": "{argument name=\"main character description\" default=\"Young Japanese office worker in a suit\"}",
    "theme": "{argument name=\"core concept\" default=\"Surrounded by a large group of clones who look exactly like him\"}"
  },
  "layout": {
    "left_page": {
      "type": "Full-page spread large image",
      "setting": "{argument name=\"setting\" default=\"Shibuya Crossing at night\"}",
      "visuals": "The protagonist stands alone in the middle of a crossroads, looking around in shock at the crowd of people around him, all of whom are his own clones.",
      "text_elements": [
        {
          "type": "manga title logo",
          "text": "{argument name=\"manga title\" default=\"A city full of me\"}"
        },
        {
          "type": "subtitle",
          "text": "Episode 1 Explanation"
        },
        {
          "type": "narration box",
          "text": "That night, the world quietly abandoned me."
        },
        {
          "type": "sound effect",
          "text": "noisy……"
        }
      ]
    },
    "right_page": {
      "type": "5-grid vertical layout",
      "panels": [
        {
          "panel_number": 1,
          "visuals": "A close-up of the protagonist's eyes; his pupils are dilated with shock, and he is covered in sweat.",
          "text_elements": [
            {
              "type": "speech bubble",
              "text": "Huh? Why... is everyone me?"
            },
            {
              "type": "sound effect",
              "text": "thud"
            }
          ]
        },
        {
          "panel_number": 2,
          "visuals": "A row of eight clones dressed in suits stared blankly ahead.",
          "text_elements": [
            {
              "type": "sound effect",
              "text": "noisy……"
            }
          ]
        },
        {
          "panel_number": 3,
          "visuals": "A clone leans close to the shocked protagonist and whispers in his ear.",
          "text_elements": [
            {
              "type": "speech bubble",
              "text": "Your position has already been filled."
            },
            {
              "type": "sound effect",
              "text": "Swoosh"
            }
          ]
        },
        {
          "panel_number": 4,
          "visuals": "A close-up of the smartphone screen in my hand shows a push notification.",
          "text_elements": [
            {
              "type": "screen text",
              "text": "The handover begins."
            },
            {
              "type": "sound effect",
              "text": "bite"
            }
          ]
        },
        {
          "panel_number": 5,
          "visuals": "A distant view of endless clone hordes on city streets.",
          "text_elements": [
            {
              "type": "narration box",
              "text": "The first thing to disappear is not the name, nor the life. It is the place to live."
            },
            {
              "type": "bottom left text",
              "text": "Do I really still deserve to stay here?"
            },
            {
              "type": "bottom right text",
              "text": "{argument name=\"cliffhanger text\" default=\"Next episode preview!\"}"
            },
            {
              "type": "sound effect",
              "text": "Noisy... Noisy... Noisy..."
            }
          ]
        }
      ]
    }
  }
}

